/** The Long Silence: original rescue/investigation campaign, woven around Farwake's existing Earth canon. */
const person=(id,name,systemId,bodyId,roleLabel,text)=>({id,name,systemId,bodyId,role:'contact',roleLabel,text,color:'#a9c9d6',species:'human'});
export const EARTH_CAMPAIGN_ID='earth_long_silence';
export const EARTH_CAMPAIGN_CONTACTS=[
 person('earth-ines','Ines Calder','hearth','morrow','Earth correspondence archivist','Ines keeps the unanswered letters in waterproof tins. A household on Earth changed its address six days ago. “If they can move house, why can none of us get an answer?”'),
 person('earth-vale','Oren Vale','hearth','kettle','Homeward relief dispatcher','Oren has a spare headset and a wall of missing ships. “Ines is following an old Earth signal. We need pilots who bring people back, not just interesting wreckage.”'),
 person('earth-jun','Jun Venn','vesper','listening','Evacuation records specialist','Jun lays three passenger lists side by side. The names agree. The arrival counts do not.'),
 person('earth-tess','Tess Amadi','brindle','weighhouse','Relief convoy coordinator','Tess has kept the same departure window open for seventeen years. “People still arrive carrying tickets for a ship we never saw.”'),
 person('earth-ryn','Auditor Eren','meridian','ledger','Public ledger examiner','Eren marks the difference between a lawful quarantine and a bill that never stops collecting interest.'),
 person('earth-sef','Doctor Nima','nacre','bastion','Evacuation receiving officer','Nima asks for the patient before the paperwork. Every occupied recovery bed has a name above it.'),
 person('earth-ot','Ot Pell','hush','blindpost','Decommissioned relay custodian','Ot tends a transmitter that was ordered to be silent. Its maintenance log has been answering a machine instead of a government.'),
 person('earth-sol','Commander Suri','sol','threshold','Threshold civilian liaison','Suri wears a rescue-service badge. “Permission to approach is permission to visit. The people below never agreed to become someone else’s prize.”'),
 person('earth-lio','Lio Arendt','sol','earth','Watershed council historian','Lio has lived on Earth all her life. “Tell me what they taught you about us. Then I can show you what they left out.”')
];
export const EARTH_CAMPAIGN_OBJECTS=[
 {id:'earth-listening-manifest',name:'Evacuation census splice',systemId:'vesper',bodyId:'listening',kind:'terminal',text:'The household registry is current. The fleet archive keeps classifying the same people as passengers who have not yet departed.'},
 {id:'earth-brindle-manifest',name:'Unclaimed convoy manifest',systemId:'brindle',bodyId:'weighhouse',kind:'evidence',text:'Medical pallets were relabeled as proprietary atmospheric equipment at a dock they never visited.'},
 {id:'earth-ledger-contract',name:'Emergency administration ledger',systemId:'meridian',bodyId:'ledger',kind:'terminal',text:'The emergency ended. Its administration fees did not. A renewal stamp is signed by an automated procurement office.'},
 {id:'earth-hush-order',name:'Unrevoked interdiction order',systemId:'hush',bodyId:'blindpost',kind:'terminal',text:'The final valid order protects rebuilding habitats. An appended rule treats every unlisted relief ship as an extraction fleet.'},
 {id:'earth-witness-log',name:'Witness portable approach log',systemId:'witness',bodyId:'stillwater',kind:'evidence',text:'A duplicate of the portable approach log survives independently of the climate model. Its timestamps record decades of patient atmospheric repair.'},
 {id:'earth-council-archive',name:'Watershed assembly archive',systemId:'sol',bodyId:'earth',kind:'terminal',text:'Flood maps, seed budgets, hospital shifts, local elections. Earth’s survival was a long series of ordinary decisions made under extraordinary pressure.'},
 {id:'earth-recall-console',name:'Interdiction recall terminal',systemId:'sol',bodyId:'threshold',kind:'terminal',text:'A lawful recall needs three things: the original emergency order, a current council signature, and the live fleet acknowledgement.'}
];
const all=Object.fromEntries([...EARTH_CAMPAIGN_CONTACTS,...EARTH_CAMPAIGN_OBJECTS].map(v=>[v.id,v]));
const at=id=>{const v=all[id];return{systemId:v.systemId,bodyId:v.bodyId,entityId:`quest:${id}`,...(v.role?{contactId:id}:{objectId:id})};};
const space=(systemId,anchorBody,offsetX,offsetY)=>({systemId,anchorBody,offsetX,offsetY});
const stage=(mission,id,title,kind,target,text,objective,extra={})=>({mission,id,title:`${String(mission).padStart(2,'0')} · ${title}`,kind,at:target,text,objective,actionLabel:'Record the evidence',...extra});
const talk=(mission,id,title,contact,text,objective,extra={})=>stage(mission,id,title,'talk',at(contact),text,objective,{actionLabel:'Continue the conversation',...extra});
const gate=(mission,id,title,entity,flags,text,objective)=>stage(mission,id,title,'earth-gate',at(entity),text,objective,{requiresFlags:flags,requirementText:objective,actionLabel:'Confirm the completed investigation'});
const scan=(mission,id,title,target,text,objective,extra={})=>stage(mission,id,title,'earth-scan',target,text,objective,{actionLabel:'Take the close-range reading',...extra});
const rescue=(mission,id,title,target,passenger,text,objective)=>stage(mission,id,title,'earth-rescue',target,text,objective,{passenger,actionLabel:`Recover ${passenger.name} · 1 berth`});
const deliver=(mission,id,title,contact,rescueId,text,objective)=>stage(mission,id,title,'earth-deliver',at(contact),text,objective,{rescueId,actionLabel:'Disembark the survivor at this drop zone'});
const defend=(mission,id,title,target,text,objective,{duration=36,waves=[{at:0,count:1,hp:64},{at:16,count:1,hp:80}],integrity=100,escort=false}={})=>stage(mission,id,title,'earth-defense',target,text,objective,{duration,waves,integrity,escort,deadline:duration+120,actionLabel:'Confirm the corridor is secure'});
const options=(ids,labels=ids)=>ids.map((id,i)=>({id:String(id),label:String(labels[i])}));
const puzzle=(mission,id,title,entity,text,objective,clues,labels,ids,solution)=>stage(mission,id,title,'puzzle',at(entity),text,objective,{actionLabel:'Verify the reconstructed record',puzzle:{type:'evidence',prompt:'Use the surviving records to put each item in its proper place.',clues,inputs:labels.map((label,i)=>({id:`record-${i}`,label,options:options(ids)})),solution}});
const choice=(mission,id,title,contact,text,objective,choices)=>stage(mission,id,title,'choice',at(contact),text,objective,{options:choices});
const decision=(id,label,detail,rep,flag,memory,cost={})=>({id,label,detail,cost,effects:{rep,flags:[flag],memory}});

export const EARTH_CAMPAIGN={
 id:EARTH_CAMPAIGN_ID,title:'Earth: The Long Silence',category:'Earth campaign',offeredBy:'earth-ines',alsoOfferedBy:['earth-vale'],remoteAccept:true,missionCount:16,
 summary:'Follow Earth’s unanswered messages through sixteen investigations and relief operations. Recover survivors, protect their route home, and uncover the orders still enforcing Earth’s silence. The first lead is available over comms; travel, evidence, rescues, and landing clearance must be earned.',
 reward:900,
 stages:[
  talk(1,'invitation','The letters that came back','earth-ines','Ines sends you a copy of a letter marked ADDRESS UPDATED, six days ago. Earth is supposed to be silent. Oren at Kettle will coordinate the journey. Start with the old evacuation beacon near Tinbell; its civilian records survived inside a military carrier signal.','Begin at Hearth. Follow A ship of your own and Something in the belt, then examine Tinbell’s evacuation frequency.'),
  scan(1,'tinbell-reading','A voice under the carrier',space('hearth','tinbell',310,170),'Beneath the household update is a fresh distress burst from a relief mechanic. Someone is still using an ancient evacuation frequency. It points to a damaged survival pod outside Tinbell’s debris field.','Complete Something in the belt: meet Iona, finish a local job, mine six ore, and scan Tinbell’s beacon. Then take the marked close-range reading.',{requiresFlags:['belt_signal_found'],requirementText:'Finish the existing Something in the belt chapter, including the real Tinbell beacon scan. The Earth investigation cannot manufacture that evidence.'}),
  rescue(2,'tinbell-rescue','The last seat out',space('hearth','tinbell',810,-230),{id:'engineer-aru',name:'Aru Sen',role:'relief engineer'},'Aru’s pod is tumbling slowly. The mechanic was checking a forgotten relay when an unmanned ship ordered the tug to evacuate—and fired before the answer. There is one survivor. The capsule must transfer to an empty berth aboard your own or a permitted crew ship; Kettle’s shipyard can provide a larger hull if every berth is occupied.','Fly to Aru’s marked survival pod near Tinbell with one free berth, and recover the survivor.'),
  deliver(3,'kettle-drop','A name on the recovery board','earth-vale','tinbell-rescue','Aru walks into Kettle’s receiving bay under their own power. They recognize the old interdiction carrier. Once treated, they can send shielding procedures to any relief relay you defend. Saving this person has added something a black box could not.','Bring the actual ship carrying Aru to Kettle. Meet Oren at the marked relief drop zone.'),
  gate(4,'listening-access','A household still moving','earth-jun',['archive_decoded'],'Jun will not turn a rumor into a rescue route. Help repair Listening House and let Sera authenticate the current household census. Its address changes are ordinary, and that is the extraordinary part.','In Vesper, complete A household on Earth: repair a relay at Listening House, then speak to Sera and verify the census. Meet Jun afterward.'),
  puzzle(4,'listening-record','Three clocks, one family','earth-listening-manifest','The oldest clock is an evacuation departure. A second records a communications closure. The third is last week’s household move. Earth was alive after the sky went quiet; the quiet was a policy, not a death certificate.','Reconstruct the three timestamps at Listening House.',
   ['The evacuation departure predates the communications closure.','The household move happened last week, after both emergency events.','Read from oldest to newest.'],['Oldest record','Middle record','Newest record'],['evacuation','closure','household'],['evacuation','closure','household']),
  puzzle(5,'brindle-record','The ships that never arrived','earth-brindle-manifest','A relief convoy was charged for a route it could not use. Its medical supplies went to a holding depot while its passengers vanished from the public count. The navigation imprint points to Checkpoint Sable.','Match the actual cargo records at the Weighhouse in Brindle.',
   ['The blue seal belongs to the hospital’s medicine.','The orange seal belongs to replacement air filters.','The white seal is a passenger manifest, not freight.'],['Blue seal','Orange seal','White seal'],['medicine','filters','people'],['medicine','filters','people']),
  choice(5,'manifest-choice','Who gets the passenger names?','earth-tess','Tess can publicize the stolen relief route, but the manifest also identifies families hiding from debt collectors. She asks what to release before the next convoy departs.','Speak to Tess at the Weighhouse and decide how to share the evidence.',[
   decision('redact','Publish the theft; protect the families','Publicly expose the false charges while removing private addresses.',{freewake:5,lantern:4,meridian:-2},'earth_manifest_redacted','You exposed the diversion without handing over the families’ addresses.'),
   decision('witnesses','Give verified investigators the full record','A smaller circle receives the names under an explicit protection agreement.',{lantern:5,concord:3},'earth_manifest_sealed','You entrusted the complete manifest to named investigators, with protections for its witnesses.'),
   decision('public','Publish the complete manifest','Families can find missing relatives directly, but creditors can find them too.',{freewake:4,meridian:3,lantern:-2},'earth_manifest_public','You made every name public, helping reunions and exposing vulnerable families.')]),
  defend(6,'brindle-defense','Between departure windows',space('brindle','weighhouse',650,280),'The Weighhouse’s relief relay must stay online while Tess moves the convoy through its departure window. Unmanned interception craft are following the old carrier frequency. Disable or destroy the marked attackers and remain on watch until the transfer is complete.','Begin the relay defense at the marked point outside the Weighhouse. Protect its integrity, remain within 900 m, and neutralize both attacking waves.'),
  gate(7,'ledger-ally','A seat without an owner','earth-ryn',['ally_chosen'],'The investigation needs a public sponsor to challenge the emergency ledger. Your chosen faction can help, but sponsorship does not make Earth its property. Eren insists that the agreement be signed in the open.','At Ledger Ring, complete Who owns a way home? by choosing a faction ally. Bring the signed support to Auditor Eren.'),
  puzzle(7,'ledger-record','The emergency that paid dividends','earth-ledger-contract','An automated administration trust renewed its own fees whenever contact remained closed. Several governments inherited the arrangement; none checked the order against the living population it claimed to protect. The silence had become profitable.','Audit the three authorizations in Ledger Ring’s emergency ledger.',
   ['Only the watershed councils can consent on behalf of Earth’s residents.','The relief service certifies medical need, not ownership.','The administration trust collects fees; it cannot authorize a permanent closure.'],['Resident consent','Medical need','Fee collection'],['councils','relief','trust'],['councils','relief','trust']),
  rescue(8,'sable-rescue','The witness at the checkpoint',space('sable','checkpoint',720,-220),{id:'witness-sada',name:'Sada Ilyan',role:'relay operator'},'Sada fled a holding depot with a live revocation receipt. Their transport was disabled near Checkpoint Sable. The receipt says Earth revoked one part of the emergency order years ago; the outer network never acknowledged it.','Recover Sada from the marked capsule near Checkpoint Sable. A real spare berth is required.'),
  defend(8,'sable-escort','A slow ship in a loud sky',space('sable','checkpoint',1080,280),'The relief tug carrying the remaining depot crew cannot fold until its drive cools. Sada guides it through the checkpoint’s blind corridor from your passenger seat. Stay close while the tug moves, then clear the pursuing interceptors.','Escort the moving relief-tug marker. Remain within 900 m, keep its integrity above zero, and neutralize the pursuit before it folds.',{duration:42,escort:true,waves:[{at:0,count:1,hp:80},{at:20,count:2,hp:64}]}),
  deliver(9,'bastion-drop','The beds behind the numbers','earth-sef','sable-rescue','Sada gives Nima the names of everyone left in the depot. The relief tug’s crew reaches the ward by its own route. Sada also sends you a field patch that buys damaged transmitters more time. The rescued people have become part of the rescue effort.','Dock the actual ship carrying Sada at Bastion Three in Nacre and meet Doctor Nima at the receiving bay.'),
  choice(9,'hospital-choice','The next shipment','earth-sef','Nima can pass the depot coordinates to a faction fleet or organize a civilian evacuation. The fleet has stronger escorts; the civilians have earned the prisoners’ trust. Either way, the medical list stays with the clinic.','Choose who will coordinate the remaining depot evacuation at Bastion Three.',[
   decision('civilian','Back a civilian rescue corridor','Relief crews lead; armed escorts answer to the clinic’s timetable.',{freewake:5,lantern:5,concord:-2},'earth_relief_civilian','You put the clinic and civilian relief crews in charge of the depot evacuation.'),
   decision('fleet','Ask the fleet to secure the route','Military escorts protect the convoy; inspections will be stricter.',{concord:5,lantern:3,cinder:-2},'earth_relief_fleet','You asked the fleet to secure the depot route while the clinic retained the passenger records.')]),
  puzzle(10,'hush-recall','The command nobody revoked','earth-hush-order','Ot’s archive contains the missing acknowledgement. Earth’s councils revoked forced evacuation after the atmosphere stabilized. The outer trust accepted the message as a billing amendment, leaving armed enforcement untouched. No secret alien army is necessary for a disaster that nobody will take responsibility for.','At Blindpost in Hush, reconstruct the revocation chain.',
   ['First authenticate the original emergency order.','Then attach the current council revocation.','Only after both signatures match may the fleet receipt be requested.'],['First attachment','Second attachment','Final request'],['order','revocation','receipt'],['order','revocation','receipt']),
  talk(10,'hush-testimony','An omission with a signature','earth-ot','Ot signed a maintenance extension without reading what it maintained. Others did the same, some through fear and some for money. The original quarantine gave Earth time to heal. The unaccountable machinery around it learned to treat that healing as a threat to its own purpose.','Hear Ot’s testimony at Blindpost, then take the original route to Witness.'),
  gate(11,'witness-clearance','The weather kept growing','earth-witness-log',['vault_recovered','homeward_signal'],'The safe route is in the existing Witness climate archive. Whether you preserve the model, remove its core, or leave it to researchers, the portable approach log remains real evidence. It gives you a way to ask permission, never a right to land.','At Stillwater in Witness, complete Seeds for a future and recover the climate record’s safe approach log.'),
  scan(11,'witness-reading','The living side of the silence',space('witness','census',610,-300),'A current atmospheric checksum matches the old model’s predictions. Earth was not secretly empty. Its people rebuilt river basins, rationed industrial heat, and kept the sky closed to mass extraction while the land recovered. The mistake was allowing an external fleet to enforce yesterday’s limits forever.','Take a close-range reading beside Witness’s Census Relay.'),
  defend(12,'witness-defense','Keep the evidence on the air',space('witness','census',760,220),'Census Relay begins broadcasting the signed revocation. The old enforcement network responds as if the message were an attack. Keep the relay intact long enough for independent receivers to copy the proof. Aru’s shielding work and Sada’s field patch improve its chances if you brought them safely ashore.','Defend Census Relay through three waves. Remain within 900 m and neutralize the attackers while the evidence uploads.',{duration:54,integrity:110,waves:[{at:0,count:1,hp:80},{at:18,count:1,hp:96},{at:36,count:1,hp:112}]}),
  gate(13,'threshold-permission','Ask the people below','earth-sol',['threshold_answered'],'Suri has the evidence and the safe approach log. The landing decision still belongs to Earth. Answer Threshold Station’s real arrival hail, and respect the corridor it grants. Nothing in your investigation substitutes for that permission.','Travel to Sol with the Witness approach log. Answer Threshold Station’s arrival transmission, then meet Commander Suri on Threshold.'),
  talk(14,'earth-neighbors','The people who stayed','earth-lio','Lio shows you a school built on a former seawall. There was no single day Earth ended. Crop failures, extraction, and unequal evacuations broke the old order. People who could not leave formed the watershed councils; their atmospheric pact made recovery possible. Some departing powers called the silence a grave because a living, independent Earth complicated their claims.','Land legally on Earth and meet Lio at the watershed archive.'),
  puzzle(14,'earth-record','A history with ordinary names','earth-council-archive','The council record separates three decisions that distant histories collapsed into one: evacuate people in immediate danger; limit traffic while Earth recovered; revoke forced evacuation after recovery. The last decision never reached the guns that claimed to enforce the first.','Reconstruct the surviving council record on Earth.',
   ['Emergency evacuation came first, while settlements flooded.','The atmospheric pact limited traffic during rebuilding.','The elected councils revoked forced evacuation after recovery milestones were met.'],['First decision','Rebuilding decision','Latest decision'],['evacuate','restore','revoke'],['evacuate','restore','revoke']),
  puzzle(15,'recall-authority','Three signatures to end a war','earth-recall-console','Suri will transmit the recall with Earth’s present-day consent. It is a narrow instruction: stop compulsory evacuation and accept civilian rescue traffic. It does not abolish quarantine or decide who may settle on the ground.','Return to Threshold Station and authenticate the fleet recall.',
   ['The archive provides the historical emergency order.','The watershed councils provide current consent.','The fleet itself must return the acknowledgement; a sponsor cannot sign in its place.'],['Historical authority','Current consent','Required acknowledgement'],['archive','councils','fleet'],['archive','councils','fleet']),
  defend(15,'sol-defense','The last evacuation order',space('sol','luna',920,340),'The recall beacon speaks with all three authorities. A remaining interdiction wing attempts to silence it before the acknowledgement finishes. Keep the beacon alive, hold the corridor, and disable or destroy every marked enforcer. Civilian ships in this system can see the same battle and help.','Protect the recall beacon outside Luna for the final transmission. Three escalating waves must be neutralized; the beacon must survive.',{duration:66,integrity:125,waves:[{at:0,count:2,hp:80},{at:22,count:2,hp:96},{at:44,count:2,hp:112}]}),
  rescue(15,'sol-rescue','One more light on the board',space('sol','luna',530,-300),{id:'keeper-emi',name:'Emi Raal',role:'civilian beacon keeper'},'A maintenance keeper ejected when the enforcement wing fired on its own relay. The recall has stopped the surviving fleet’s compulsory evacuation routines. Emi is still waiting in the dark. Winning the argument did not finish the rescue.','Recover Emi’s capsule near Luna with one free berth.'),
  deliver(16,'earth-homecoming','A place at the table','earth-lio','sol-rescue','Emi steps onto Earth carrying a maintenance bag and an empty water bottle. Lio adds their name to the return register. The oldest question now has a human answer: Earth survived, and its people were never a resource waiting to be claimed.','Bring the ship carrying Emi to Earth’s legal landing corridor and disembark at Lio’s receiving point.'),
  gate(16,'earth-council-future','The sky belongs to whom?','earth-lio',['council_decision_made'],'The enforcement failure has been exposed. How Earth reopens contact is still the council’s separate decision, with all the difficult tradeoffs you already know. Carry the agreement you actually choose, not one the investigation chooses for you.','Complete the existing Earth council conversation and choose its agreement. Return to Lio to decide how to preserve the evidence.'),
  choice(16,'earth-legacy','What we carry home','earth-lio','The investigation is complete. Earth survived through local rebuilding and a protective atmospheric pact. A chain of profitable extensions, neglected acknowledgements, and inherited orders turned temporary protection into enforced isolation. The testimony names institutions and decisions, not a single convenient villain. Lio asks how the evidence should outlive you.','Choose the public legacy of the Long Silence investigation.',[
   decision('public-record','Publish a verified public history','Everyone can check the orders, testimony, and failures. Private household coordinates remain protected.',{freewake:8,lantern:10,meridian:-4},'earth_history_public','You published the verified history of the Long Silence while protecting private household coordinates.'),
   decision('witness-custody','Place the full record in independent witness custody','Survivors and Earth’s councils hold the originals; public findings remain available and disputed claims require a hearing.',{lantern:10,concord:5},'earth_history_custody','You placed the original evidence under independent survivor and council custody, with public findings and a right to challenge them.'),
   decision('regional-copies','Give each region an independently verifiable copy','No single capital controls the record. Local communities decide how to teach and preserve it.',{freewake:10,cinder:6,meridian:-3},'earth_history_regional','You distributed verifiable copies to Earth’s regions and outer relief communities so no single authority could erase the record again.')])
 ]
};
